// Node "Préparer la demande IA" — mode : Run Once for All Items
// Entrées : le formulaire, l'onglet Parc et l'onglet Dégâts lus juste avant.
const form = $('Formulaire dégât').first().json;
const parc = $('Lire Parc').all().map(i => i.json).filter(r => r.id);
const types = ['Déchirure toile', 'Boudin percé', 'Bride / ligne', 'Choc planche / délaminage', 'Foil (mât, fuselage, ailes)', 'Harnais (sangle, boucle)', 'Autre'];
const message = form["Ce qui s'est passé"] || '';

const prompt = `Tu es "Le Gréeur", l'agent qui tient le fichier matos d'une école de kitesurf et de wingfoil.
Un moniteur signale un dégât en langage courant. Associe-le à UNE pièce du parc et structure-le.

PARC (JSON) : ${JSON.stringify(parc.map(p => ({ id: p.id, designation: p.designation, achat: p.date_achat })))}
TYPES DE DÉGÂT AUTORISÉS : ${JSON.stringify(types)}
GRAVITÉS AUTORISÉES : ["Légère","Moyenne","Grave"]

Règles :
- "id" : l'ID de la pièce visée. S'il reste un doute, mets la plus probable et liste les autres dans "candidats".
- "immobiliser" : true si la pièce ne doit pas ressortir avant réparation (sécurité, prise d'eau, structure, boudin percé, toile très déchirée, boucle de harnais cassée).
- "description" : reformulation courte et factuelle, en français.
- "question" : une question courte à poser au moniteur s'il manque une info importante, sinon "".
- N'invente aucun prix.
Réponds UNIQUEMENT avec un objet JSON : {"id":"...","candidats":["..."],"type":"...","gravite":"...","immobiliser":true,"description":"...","question":""}

MESSAGE DU MONITEUR : """${message}"""`;

return [{ json: { body: { model: 'claude-haiku-5-5', max_tokens: 1500, thinking: { type: 'disabled' }, messages: [{ role: 'user', content: prompt }] } } }];

// Règles de calcul du Gréeur — MÊMES règles que le démonstrateur web.
// Hypothèses de départ, à caler avec l'école (voir greeur/docs/regles.md).
// Ce bloc est recopié en tête des nodes Code par tools/build.py.
const HYP = {
  duree_vie_ans: { 'Voile kite': 3, 'Aile wing': 3, 'Planche twintip': 4, 'Planche wingfoil': 5, 'Foil': 5, 'Harnais': 2, 'Barre': 3 },
  seuil_reparations_pct: 50,
  surveiller_age_pct: 80,
  surveiller_reparations_pct: 30,
  surveiller_nb_degats_6_mois: 2,
  revente_pct: 20,
};
const DAY = 864e5;
// Accepte 2024-03-10 et 10/03/2024 (format d'affichage français de Google Sheets)
const toDate = s => {
  const t = String(s ?? '').trim(), fr = t.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  const d = fr ? new Date(+fr[3], +fr[2] - 1, +fr[1], 12) : new Date(t.slice(0, 10) + 'T12:00:00');
  return isNaN(d) ? null : d;
};
const addYears = (d, y) => { const r = new Date(d); r.setMonth(r.getMonth() + Math.round(y * 12)); return r; };
const num = v => { const n = parseFloat(String(v ?? '').replace(',', '.')); return isNaN(n) ? 0 : n; };
const yes = v => /^(o|oui|true|1|y)/i.test(String(v ?? ''));

function statut(it, degats, today) {
  const life = HYP.duree_vie_ans[it.categorie] || 3;
  const achat = toDate(it.date_achat) || today;
  const age = (today - achat) / (365.25 * DAY);
  const fin = addYears(achat, life);
  const dg = degats.filter(d => d.id === it.id);
  const cumul = dg.reduce((s, d) => s + num(d.cout), 0);
  const prix = num(it.prix_achat);
  const pct = prix ? (cumul / prix) * 100 : 0;
  const immo = dg.some(d => d.statut !== 'Réparé' && yes(d.immobilise));
  const recent = dg.filter(d => (today - toDate(d.date)) / DAY <= 183).length;
  const why = [];
  let st = 'OK';
  if (fin <= today) why.push(`fin de vie estimée dépassée (${life} ans)`);
  if (pct >= HYP.seuil_reparations_pct) why.push(`réparations = ${Math.round(pct)} % du prix`);
  if (why.length) st = 'À remplacer';
  else {
    if ((age / life) * 100 >= HYP.surveiller_age_pct) why.push(`${Math.round((age / life) * 100)} % de sa durée de vie`);
    if (pct >= HYP.surveiller_reparations_pct) why.push(`réparations = ${Math.round(pct)} % du prix`);
    if (recent >= HYP.surveiller_nb_degats_6_mois) why.push(`${recent} dégâts en 6 mois`);
    if (why.length) st = 'À surveiller';
  }
  if (immo) { st = 'Immobilisé'; why.unshift('réparation en attente, ne pas sortir'); }
  const remplacement = pct >= HYP.seuil_reparations_pct ? today : fin;
  return { ...it, prix, age, cumul, pct, st, why, remplacement };
}

function estimation(type, degats) {
  const c = degats.filter(d => d.type === type && num(d.cout) > 0).map(d => num(d.cout)).sort((a, b) => a - b);
  if (!c.length) return { montant: null, texte: 'à chiffrer (aucune réparation de ce type dans l\'historique)' };
  const m = c.length % 2 ? c[(c.length - 1) / 2] : (c[c.length / 2 - 1] + c[c.length / 2]) / 2;
  return { montant: m, texte: `≈ ${Math.round(m)} € (médiane de ${c.length} réparation(s) du même type)` };
}

// Node "Construire la ligne Dégâts" — mode : Run Once for All Items
// Lit la réponse de Claude, vérifie l'ID, calcule l'estimation à partir de l'historique (jamais inventée par l'IA).
// La ligne va dans l'onglet Dégâts ; la page web l'affiche dans « À traiter ».
const today = new Date(); today.setHours(12, 0, 0, 0);
const form = $('Formulaire dégât').first().json;
const parc = $('Lire Parc').all().map(i => i.json).filter(r => r.id);
const degats = $('Lire Dégâts').all().map(i => i.json).filter(r => r.id);
// Le modèle peut renvoyer un bloc « thinking » avant le texte : on ne garde que les blocs texte.
const raw = ($input.first().json.content || []).filter(b => b.type === 'text').map(b => b.text).join('');

let j = {};
try { j = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { j = {}; }
const piece = parc.find(p => p.id === j.id);
const type = j.type || 'Autre';
const est = estimation(type, degats);
const avant = piece ? statut(piece, degats, today).st : '?';

const ligne = {
  date: today.toISOString().slice(0, 10),
  id: piece ? piece.id : 'A_VERIFIER',
  type,
  description: (j.description || form["Ce qui s'est passé"] || '').trim(),
  gravite: j.gravite || 'Moyenne',
  cout: '',
  statut: 'À réparer',
  immobilise: j.immobiliser ? 'oui' : 'non',
};
const apres = piece ? statut(piece, [...degats, ligne], today).st : '?';

// Résumé lisible dans l'historique des exécutions n8n (ignoré par la Google Sheet).
const resume = piece
  ? `${j.immobiliser ? 'NE PAS SORTIR' : 'À contrôler'} : ${piece.id} (${piece.designation}). ${type}, ${String(ligne.gravite).toLowerCase()}. Réparation : ${est.texte}. État : ${avant} → ${apres}.`
  : `Pièce non identifiée, à vérifier à la main. Message : ${form["Ce qui s'est passé"]}`;

return [{ json: { ...ligne, _resume: resume, _question: j.question || '', _candidats: (j.candidats || []).join(', ') } }];
